def obtener_stickers_por_categoria(categoria: str):
    """Filtra y devuelve stickers según la categoría solicitada."""
    return {k: v for k, v in STICKERS_DB.items() if v.get("cat") == categoria}

def buscar_stickers(query: str):
    """Busca stickers por nombre o clave."""
    query = query.lower()
    return {k: v for k, v in STICKERS_DB.items() if query in k or query in v.get("name", "").lower()}
